<?php get_header();$can_access=current_user_can('gmr_view_collector_area')||current_user_can('gmr_manage_artworks');?>
<?php if(!is_user_logged_in()):?><section class="gmr-private"><div class="gmr-private__panel"><span class="gmr-kicker">Acceso privado</span><h1>Coleccionistas</h1><?php if(isset($_GET['access'])&&'inactive'===sanitize_key(wp_unslash($_GET['access']))):?><div class="gmr-private__notice">Esta cuenta no esta activa. Contacte a la galeria.</div><?php endif;?><p>Consulte el catalogo completo, precios y documentos reservados por la galeria.</p><?php wp_login_form(array('redirect'=>get_permalink(),'label_username'=>'Correo o usuario','label_password'=>'Contrasena','label_log_in'=>'Ingresar','remember'=>true));?><p><a href="<?php echo esc_url(wp_lostpassword_url(get_permalink()));?>">Recuperar contrasena</a></p></div></section>
<?php elseif(!$can_access):?><section class="gmr-private"><div class="gmr-private__panel"><h1>Acceso restringido</h1><p>Su cuenta no tiene acceso al area de Coleccionistas. Contacte a la galeria.</p><a class="gmr-button" href="<?php echo esc_url(wp_logout_url(home_url('/')));?>">Cerrar sesion</a></div></section>
<?php else:$private=new WP_Query(array('post_type'=>'product','post_status'=>'publish','posts_per_page'=>12,'meta_query'=>array(array('key'=>'gmr_visibility','value'=>array('public','collectors'),'compare'=>'IN'))));$available_query=new WP_Query(array('post_type'=>'product','post_status'=>'publish','fields'=>'ids','posts_per_page'=>1,'meta_query'=>array(array('key'=>'gmr_visibility','value'=>array('public','collectors'),'compare'=>'IN'),array('key'=>'gmr_commercial_status','value'=>'available'))));$available=(int)$available_query->found_posts;?><header class="gmr-private-head"><div class="gmr-wrap"><span class="gmr-kicker">Area privada</span><h1>Bienvenido, <?php echo esc_html(wp_get_current_user()->display_name);?></h1><p><?php echo esc_html($private->found_posts);?> obras autorizadas · <?php echo esc_html($available);?> disponibles</p><div class="gmr-private-nav"><a href="<?php echo esc_url(get_post_type_archive_link('product'));?>">Catalogo completo</a><a href="<?php echo esc_url(add_query_arg('estado','available',get_post_type_archive_link('product')));?>">Obras disponibles</a><a href="<?php echo esc_url(gmr_theme_page_url('colecciones'));?>">Colecciones</a><a href="<?php echo esc_url(wp_logout_url(home_url('/')));?>">Cerrar sesion</a></div></div></header><section class="gmr-section"><div class="gmr-wrap"><div class="gmr-section__head"><div><span class="gmr-kicker">Seleccion privada</span><h2>Catalogo para Coleccionistas</h2></div><a class="gmr-button" href="<?php echo esc_url(get_post_type_archive_link('product'));?>">Ver catalogo completo</a></div><div class="gmr-grid"><?php while($private->have_posts()){$private->the_post();get_template_part('template-parts/artwork','card');}wp_reset_postdata();?></div></div></section><?php endif;get_footer();?>
